sealed class AndroidException(message: String): kotlin.Exception(message) {
        
        class AuthFailed(message: String) : AndroidException(message)
        
        class FormatException(message: String) : AndroidException(message)
        
        class Io(message: String) : AndroidException(message)
        
        class NotFound(message: String) : AndroidException(message)
        
        class AlreadyExists(message: String) : AndroidException(message)
        
        class PermissionDenied(message: String) : AndroidException(message)
        
        class Closed(message: String) : AndroidException(message)
        

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<AndroidException> {
        override fun lift(error_buf: RustBuffer.ByValue): AndroidException = FfiConverterTypeAndroidError.lift(error_buf)
    }
}

/**
 * @suppress
 */
public object FfiConverterTypeAndroidError : FfiConverterRustBuffer<AndroidException> {
    override fun read(buf: ByteBuffer): AndroidException {
        
            return when(buf.getInt()) {
            1 -> AndroidException.AuthFailed(FfiConverterString.read(buf))
            2 -> AndroidException.FormatException(FfiConverterString.read(buf))
            3 -> AndroidException.Io(FfiConverterString.read(buf))
            4 -> AndroidException.NotFound(FfiConverterString.read(buf))
            5 -> AndroidException.AlreadyExists(FfiConverterString.read(buf))
            6 -> AndroidException.PermissionDenied(FfiConverterString.read(buf))
            7 -> AndroidException.Closed(FfiConverterString.read(buf))
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
        
    }

    override fun allocationSize(value: AndroidException): ULong {
        return 4UL
    }

    override fun write(value: AndroidException, buf: ByteBuffer) {
        when(value) {
            is AndroidException.AuthFailed -> {
                buf.putInt(1)
                Unit
            }
            is AndroidException.FormatException -> {
                buf.putInt(2)
                Unit
            }
            is AndroidException.Io -> {
                buf.putInt(3)
                Unit
            }
            is AndroidException.NotFound -> {
                buf.putInt(4)
                Unit
            }
            is AndroidException.AlreadyExists -> {
                buf.putInt(5)
                Unit
            }
            is AndroidException.PermissionDenied -> {
                buf.putInt(6)
                Unit
            }
            is AndroidException.Closed -> {
                buf.putInt(7)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




